import { randomUUID } from 'node:crypto';
import { constants } from 'node:fs';
import { lstat, open, readdir, unlink } from 'node:fs/promises';
import { join } from 'node:path';
import type { BrowserDownload } from '../../ports/computer.ts';
import { fileBytes, fileName } from '../../shared/files.ts';

export function downloadName(value: string | undefined, pdf = false): string {
  const name = value ?? (pdf ? 'download.pdf' : 'download');
  if (!name.trim() || /[/\\\u0000-\u001f\u007f]/.test(name) || name === '.' || name === '..')
    throw new Error('A plain download filename is required.');
  return fileName(name);
}

export function downloadFile(bytes: Buffer, name?: string, mimeType?: string): BrowserDownload {
  if (!bytes.length || bytes.length > fileBytes)
    throw new Error(
      `Browser downloads must be between one byte and ${fileBytes / 1024 / 1024} MiB.`,
    );
  const pdf = bytes.subarray(0, 5).toString('ascii') === '%PDF-';
  const type = pdf
    ? 'application/pdf'
    : (mimeType?.split(';')[0].trim() ?? 'application/octet-stream');
  if (type.length > 100 || !/^[a-zA-Z0-9!#$&^_.+-]+\/[a-zA-Z0-9!#$&^_.+-]+$/.test(type))
    throw new Error('The browser download type is unavailable.');
  return { bytes, name: downloadName(name, pdf), mimeType: type };
}

export function decodeDownloadChunk(value: unknown): Buffer {
  if (typeof value !== 'string' || value.length % 4 !== 0 || !/^[A-Za-z0-9+/]*={0,2}$/.test(value))
    throw new Error('The browser file is unavailable.');
  const bytes = Buffer.from(value, 'base64');
  if (bytes.toString('base64') !== value) throw new Error('The browser file is unavailable.');
  return bytes;
}

export async function completedDownloads(directory: string): Promise<string[]> {
  try {
    const root = await lstat(directory);
    if (!root.isDirectory() || root.isSymbolicLink()) throw new Error();
  } catch (error) {
    if ((error as NodeJS.ErrnoException).code === 'ENOENT') return [];
    throw new Error('The browser download directory is unavailable.');
  }
  const entries = await readdir(directory, { withFileTypes: true });
  const files = await Promise.all(
    entries
      .filter((entry) => entry.isFile() && !entry.name.endsWith('.crdownload'))
      .map(async (entry) => ({
        name: entry.name,
        modified: (await lstat(join(directory, entry.name))).mtimeMs,
      })),
  );
  return files.sort((a, b) => b.modified - a.modified).map((file) => file.name);
}

export async function readDownload(directory: string, file: string, name?: string) {
  if (!file || file.includes('/') || file.includes('\\') || file === '.' || file === '..')
    throw new Error('The browser file is unavailable.');
  const root = await lstat(directory).catch(() => undefined);
  if (!root?.isDirectory() || root.isSymbolicLink())
    throw new Error('The browser file is unavailable.');
  const handle = await open(join(directory, file), constants.O_RDONLY | constants.O_NOFOLLOW).catch(
    () => {
      throw new Error('The browser file is unavailable.');
    },
  );
  try {
    const before = await handle.stat();
    if (!before.isFile() || before.nlink !== 1 || before.size < 1 || before.size > fileBytes)
      throw new Error();
    const bytes = Buffer.alloc(before.size);
    let offset = 0;
    while (offset < bytes.length) {
      const result = await handle.read(bytes, offset, bytes.length - offset, offset);
      if (!result.bytesRead) throw new Error('The browser download changed while reading.');
      offset += result.bytesRead;
    }
    const after = await handle.stat();
    const path = await lstat(join(directory, file));
    if (
      before.size !== after.size ||
      before.mtimeMs !== after.mtimeMs ||
      before.ctimeMs !== after.ctimeMs ||
      before.ino !== path.ino ||
      before.dev !== path.dev ||
      path.isSymbolicLink()
    )
      throw new Error('The browser download changed while reading.');
    return downloadFile(bytes, name);
  } catch {
    throw new Error(`The browser file is unavailable or exceeds ${fileBytes / 1024 / 1024} MiB.`);
  } finally {
    await handle.close();
  }
}

export async function createDownloadCapture(directory: string) {
  const root = await lstat(directory);
  if (!root.isDirectory() || root.isSymbolicLink())
    throw new Error('The browser download directory is unavailable.');
  const previous = new Set(await readdir(directory));
  const file = `capture-${randomUUID()}`;
  return {
    file,
    async cleanup(closed = false) {
      const current = await lstat(directory);
      if (
        !current.isDirectory() ||
        current.isSymbolicLink() ||
        current.dev !== root.dev ||
        current.ino !== root.ino
      )
        throw new Error('The browser download directory changed.');
      for (const name of closed ? await readdir(directory) : [file]) {
        if (previous.has(name)) continue;
        await unlink(join(directory, name)).catch((error: NodeJS.ErrnoException) => {
          if (error.code !== 'ENOENT') throw error;
        });
      }
    },
  };
}

export const fetchChunkBytes = 4 * 1024 * 1024;

export function fetchDownloadScript(url: string, key: string) {
  return `(async () => {
    try {
      const response = await fetch(${JSON.stringify(url)}, { credentials: 'include' });
      if (!response.ok || !response.body || Number(response.headers.get('content-length')) > ${fileBytes}) throw new Error();
      const reader = response.body.getReader();
      const chunks = [];
      let size = 0;
      for (;;) {
        const part = await reader.read();
        if (part.done) break;
        size += part.value.length;
        if (size > ${fileBytes}) { await reader.cancel(); throw new Error(); }
        chunks.push(part.value);
      }
      const bytes = new Uint8Array(size);
      let offset = 0;
      for (const chunk of chunks) { bytes.set(chunk, offset); offset += chunk.length; }
      window[${JSON.stringify(key)}] = bytes;
      return { size, mimeType: response.headers.get('content-type') || 'application/octet-stream' };
    } catch { return null; }
  })()`;
}

export function fetchChunkScript(key: string, offset: number) {
  return `(() => {
    const bytes = window[${JSON.stringify(key)}].subarray(${offset}, ${offset + fetchChunkBytes});
    let binary = '';
    for (let index = 0; index < bytes.length; index += 32768) binary += String.fromCharCode(...bytes.subarray(index, index + 32768));
    return btoa(binary);
  })()`;
}

import * as dns from 'node:dns';
import { lookup } from 'node:dns/promises';
import { createServer, request, type OutgoingHttpHeaders } from 'node:http';
import { connect, isIP, type LookupFunction, type Socket } from 'node:net';
import { isPublicIpv4Address } from '../../shared/public-address.ts';

export type AddressResolver = (host: string) => Promise<Array<{ address: string; family: number }>>;

export function isPublicAddress(address: string): boolean {
  if (isIP(address) === 4) return isPublicIpv4Address(address);
  if (isIP(address) !== 6) return false;
  let normal: string;
  try {
    normal = new URL(`http://[${address}]`).hostname.slice(1, -1);
  } catch {
    return false;
  }
  const nat64 = /^64:ff9b::([0-9a-f]{1,4}):([0-9a-f]{1,4})$/.exec(normal);
  if (nat64) {
    const [high, low] = [parseInt(nat64[1], 16), parseInt(nat64[2], 16)];
    return isPublicAddress([high >> 8, high & 255, low >> 8, low & 255].join('.'));
  }
  return (
    /^[23][0-9a-f]{3}:/.test(normal) &&
    !/^2002:/.test(normal) &&
    !/^2001:(?::|0:|db8:|2:|10:|20:)/.test(normal) &&
    !/^3fff:[0-9a-f]{0,3}:/.test(normal)
  );
}

const systemResolver: AddressResolver = (host) => lookup(host, { all: true, verbatim: true });

async function publicAddress(hostname: string, resolver: AddressResolver) {
  const host = hostname.replace(/^\[|\]$/g, '');
  const addresses = isIP(host) ? [{ address: host, family: isIP(host) }] : await resolver(host);
  if (!addresses.length || addresses.some((item) => !isPublicAddress(item.address)))
    throw new Error('Private network destinations are blocked.');
  return addresses[0].address;
}

const connectResolver: AddressResolver = (host) =>
  new Promise((resolve, reject) =>
    dns.lookup(host, { all: true, verbatim: true }, (error, addresses) =>
      error ? reject(error) : resolve(addresses),
    ),
  );

export function publicLookup(resolver: AddressResolver = connectResolver): LookupFunction {
  return (hostname, options, callback) => {
    resolver(hostname).then(
      (answers) => {
        const addresses = answers.filter(
          (item) => !options.family || item.family === options.family,
        );
        if (!addresses.length || answers.some((item) => !isPublicAddress(item.address)))
          return callback(new Error('Private network destinations are blocked.'), '');
        if (options.all) callback(null, addresses);
        else callback(null, addresses[0].address, addresses[0].family);
      },
      (error) => callback(error, ''),
    );
  };
}

export async function publicUrl(
  value: string,
  resolver: AddressResolver = systemResolver,
): Promise<{ url: URL; address: string }> {
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    throw new Error('A valid public HTTP or HTTPS URL is required.');
  }
  if (
    !['http:', 'https:'].includes(url.protocol) ||
    url.username ||
    url.password ||
    (url.port && !['80', '443'].includes(url.port))
  )
    throw new Error('Only public HTTP and HTTPS destinations on ports 80 or 443 are permitted.');
  return { url, address: await publicAddress(url.hostname, resolver) };
}

export function browserUrl(value: string): URL {
  let url: URL;
  try {
    url = new URL(value);
  } catch {
    throw new Error('A valid HTTP or HTTPS URL is required.');
  }
  if (!['http:', 'https:'].includes(url.protocol) || url.username || url.password)
    throw new Error('Website addresses must use HTTP or HTTPS without embedded credentials.');
  return url;
}

export function createBrowserProxy(
  options: { privateNetwork?: boolean; resolver?: AddressResolver } = {},
) {
  const destination = (url: URL) =>
    options.privateNetwork
      ? Promise.resolve(url.hostname.replace(/^\[|\]$/g, ''))
      : publicAddress(url.hostname, options.resolver ?? systemResolver);
  let server: ReturnType<typeof createServer> | undefined;
  let pending: Promise<string> | undefined;
  let disposed = false;
  const sockets = new Set<Socket>();
  const track = (socket: Socket) => {
    if (sockets.has(socket)) return;
    sockets.add(socket);
    socket.once('close', () => sockets.delete(socket));
    socket.on('error', () => socket.destroy());
  };
  function url(): Promise<string> {
    if (disposed) return Promise.reject(new Error('The browser proxy has stopped.'));
    pending ??= new Promise((resolve, reject) => {
      server = createServer(async (incoming, outgoing) => {
        try {
          const url = browserUrl(incoming.url ?? '');
          if (url.protocol !== 'http:') throw new Error('Invalid proxy request.');
          const headers: OutgoingHttpHeaders = { ...incoming.headers, host: url.host };
          delete headers['proxy-authorization'];
          delete headers['proxy-connection'];
          const upstream = request(
            {
              host: await destination(url),
              port: url.port || 80,
              method: incoming.method,
              path: url.pathname + url.search,
              headers,
            },
            (response) => {
              outgoing.writeHead(response.statusCode ?? 502, response.headers);
              response.pipe(outgoing);
            },
          );
          upstream.on('socket', track);
          upstream.on('error', () => {
            if (!outgoing.headersSent) outgoing.writeHead(502);
            outgoing.end();
          });
          incoming.pipe(upstream);
        } catch {
          outgoing.writeHead(400);
          outgoing.end('Invalid browser request.');
        }
      });
      server.on('connect', async (incoming, socket, head) => {
        try {
          const url = browserUrl(`https://${incoming.url}`);
          if (url.pathname !== '/' || url.search || url.hash) throw new Error();
          const upstream = connect({
            host: await destination(url),
            port: Number(url.port || 443),
          });
          track(upstream);
          upstream.on('close', () => {
            if (!upstream.readableEnded) socket.destroy();
          });
          upstream.on('connect', () => {
            socket.write('HTTP/1.1 200 Connection Established\r\n\r\n');
            if (head.length) upstream.write(head);
            upstream.pipe(socket);
            socket.pipe(upstream);
          });
          upstream.on('error', () => socket.destroy());
          socket.on('error', () => upstream.destroy());
          socket.on('close', () => upstream.destroy());
        } catch {
          socket.end('HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n');
        }
      });
      server.on('connection', track);
      server.on('upgrade', async (incoming, socket, head) => {
        try {
          const url = browserUrl(incoming.url ?? '');
          if (url.protocol !== 'http:') throw new Error();
          const headers: OutgoingHttpHeaders = { ...incoming.headers, host: url.host };
          delete headers['proxy-authorization'];
          delete headers['proxy-connection'];
          const upstream = request({
            host: await destination(url),
            port: url.port || 80,
            method: incoming.method,
            path: url.pathname + url.search,
            headers,
          });
          upstream.on('socket', track);
          upstream.on('error', () => socket.destroy());
          upstream.on('response', (response) => {
            socket.end(
              `HTTP/1.1 ${response.statusCode ?? 502} ${response.statusMessage ?? 'Bad Gateway'}\r\nConnection: close\r\n\r\n`,
            );
            response.resume();
          });
          upstream.on('upgrade', (response, remote, remoteHead) => {
            const headers = response.rawHeaders
              .flatMap((value, index, values) =>
                index % 2 === 0 ? [`${value}: ${values[index + 1]}\r\n`] : [],
              )
              .join('');
            socket.write(
              `HTTP/1.1 ${response.statusCode ?? 101} ${response.statusMessage ?? 'Switching Protocols'}\r\n${headers}\r\n`,
            );
            if (remoteHead.length) socket.write(remoteHead);
            if (head.length) remote.write(head);
            remote.on('error', () => socket.destroy());
            socket.on('error', () => remote.destroy());
            socket.on('close', () => remote.destroy());
            remote.pipe(socket).pipe(remote);
          });
          upstream.end();
        } catch {
          socket.end('HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n');
        }
      });
      server.once('error', reject);
      server.listen(0, '127.0.0.1', () => {
        const address = server!.address();
        if (!address || typeof address === 'string')
          return reject(new Error('Browser proxy could not start.'));
        server!.unref();
        resolve(`http://127.0.0.1:${address.port}`);
      });
    });
    return pending;
  }
  return {
    url,
    async dispose() {
      disposed = true;
      await pending?.catch(() => {});
      for (const socket of sockets) socket.destroy();
      if (server?.listening)
        await new Promise<void>((resolve, reject) =>
          server!.close((error) => (error ? reject(error) : resolve())),
        );
    },
  };
}

import { randomUUID } from 'node:crypto';
import { chmod, mkdir, readFile, readdir, rename, rm, writeFile } from 'node:fs/promises';
import { connect } from 'node:net';
import { resolve } from 'node:path';
import { z } from 'zod';
import { threadIdentity } from '../../ports/thread-identity.ts';
import { BrowserActionError, browserRequestBytes } from '../../ports/computer.ts';

const storedScreen = z.object({
  version: z.literal(1),
  url: z.string(),
  sensitive: z.boolean(),
  active: z.boolean(),
  navigationFailed: z.boolean().optional(),
  restoreSession: z.boolean().optional(),
  scripted: z.boolean().optional(),
  profileId: z.uuid().optional(),
  resumeUrl: z.string().optional(),
  capturedAt: z.iso.datetime().optional(),
  timeZone: z.string().max(100).optional(),
  locale: z.string().max(35).optional(),
});
export type StoredScreen = z.infer<typeof storedScreen>;

export function createScreenStore(root: string) {
  const path = (id: string) => resolve(root, `screen-${threadIdentity(id)}.png`);
  const metadata = (id: string) => resolve(root, `screen-${threadIdentity(id)}.json`);
  return {
    path,
    async clearImage(id: string) {
      await rm(path(id), { force: true });
    },
    async profileScreens(profileId: string) {
      const files = await readdir(root).catch((error: NodeJS.ErrnoException) => {
        if (error.code === 'ENOENT') return [];
        throw error;
      });
      const ids = files
        .map((file) => /^screen-([A-Za-z0-9_-]{1,100})\.json$/.exec(file)?.[1])
        .filter((id): id is string => Boolean(id));
      const matches = await Promise.all(
        ids.map(async (id) => ((await this.load(id))?.profileId === profileId ? id : null)),
      );
      return matches.filter((id): id is string => Boolean(id));
    },
    async delete(id: string) {
      await Promise.all([rm(path(id), { force: true }), rm(metadata(id), { force: true })]);
    },
    async load(id: string): Promise<StoredScreen | null> {
      try {
        return storedScreen.parse(JSON.parse(await readFile(metadata(id), 'utf8')));
      } catch {
        return null;
      }
    },
    async save(id: string, value: StoredScreen) {
      await mkdir(root, { recursive: true, mode: 0o700 });
      const temporary = metadata(id) + '.' + randomUUID();
      await writeFile(temporary, JSON.stringify(storedScreen.parse(value)), { mode: 0o600 });
      await rename(temporary, metadata(id));
    },
    async read(id: string): Promise<Buffer | null> {
      try {
        const image = await readFile(path(id));
        return image.length ? image : null;
      } catch {
        return null;
      }
    },
    async accept(id: string, temporary: string): Promise<Buffer> {
      await chmod(temporary, 0o600);
      const buffer = await readFile(temporary);
      if (!buffer.length) throw new Error('The browser screenshot is empty.');
      await rename(temporary, path(id));
      return buffer;
    },
  };
}

export class DaemonCommandError extends Error {
  constructor(readonly detail?: string) {
    super('Browser action could not complete. Observe the page again before retrying.');
  }
}

export class DaemonTransportError extends Error {
  constructor(
    readonly kind:
      | 'timeout'
      | 'aborted'
      | 'socket_error'
      | 'socket_closed'
      | 'response_limit'
      | 'invalid_response',
  ) {
    super(
      kind === 'aborted'
        ? 'Browser observation cancelled.'
        : kind === 'response_limit'
          ? 'Browser observation exceeded its limit.'
          : 'The previous browser is unavailable.',
    );
  }
}

function interceptedClick(command: Record<string, unknown>, error: unknown): boolean {
  if (
    command.action !== 'click' ||
    typeof command.selector !== 'string' ||
    typeof error !== 'string'
  )
    return false;
  const prefix = `Element '${command.selector}' is covered by <`;
  const suffix =
    '> at its click point, so the input would land on that element instead. Dismiss or interact with the covering element first (it is often a dialog, banner, or sticky header).';
  if (!error.startsWith(prefix) || !error.endsWith(suffix)) return false;
  return /^[a-z][a-z0-9-]*(?:[#.][^<>\u0000-\u001f]{1,512}| inside [a-z][a-z0-9-]*#[^<>\u0000-\u001f]{1,512})?$/.test(
    error.slice(prefix.length, -suffix.length),
  );
}

export function daemonDeadline(command: Record<string, unknown>) {
  const operation = Number(command.timeout);
  return Math.max(60_000, (Number.isFinite(operation) ? operation : 0) + 30_000);
}

export function existingDaemonCommand(
  path: string,
  command: Record<string, unknown>,
  signal?: AbortSignal,
  timeoutMs = daemonDeadline(command),
  maxBytes = browserRequestBytes,
): Promise<Record<string, unknown>> {
  signal?.throwIfAborted();
  return new Promise((resolve, reject) => {
    const socket = connect(path);
    socket.setEncoding('utf8');
    let received = '';
    let settled = false;
    const stop = (error?: Error, data?: Record<string, unknown>) => {
      if (settled) return;
      settled = true;
      clearTimeout(deadline);
      signal?.removeEventListener('abort', abort);
      socket.destroy();
      if (error) reject(error);
      else resolve(data ?? {});
    };
    const abort = () => stop(new DaemonTransportError('aborted'));
    signal?.addEventListener('abort', abort, { once: true });
    const deadline = setTimeout(() => stop(new DaemonTransportError('timeout')), timeoutMs);
    socket.once('error', (error: NodeJS.ErrnoException) =>
      command.action === 'close' && ['ENOENT', 'ECONNREFUSED'].includes(error.code ?? '')
        ? stop(undefined, {})
        : stop(new DaemonTransportError('socket_error')),
    );
    socket.once('end', () => stop(new DaemonTransportError('socket_closed')));
    socket.once('connect', () =>
      socket.write(JSON.stringify({ id: randomUUID(), ...command }) + '\n'),
    );
    socket.on('data', (chunk: string) => {
      received += chunk;
      if (Buffer.byteLength(received) > maxBytes)
        return stop(new DaemonTransportError('response_limit'));
      const end = received.indexOf('\n');
      if (end < 0) return;
      try {
        const response = JSON.parse(received.slice(0, end));
        if (response.success === false) {
          if (interceptedClick(command, response.error))
            return stop(new BrowserActionError('browser_click_intercepted'));
          if (
            command.action === 'navigate' &&
            typeof response.error === 'string' &&
            /^Navigation failed: net::ERR_[A-Z_]+/.test(response.error)
          )
            return stop(new BrowserActionError('browser_navigation_failed'));
          return stop(
            new DaemonCommandError(typeof response.error === 'string' ? response.error : undefined),
          );
        }
        if (response.success !== true) throw new Error();
        stop(undefined, response.data ?? {});
      } catch {
        stop(new DaemonTransportError('invalid_response'));
      }
    });
  });
}

import {
  spawn,
  type ChildProcessWithoutNullStreams,
  type SpawnOptionsWithoutStdio,
} from 'node:child_process';
import { createHash } from 'node:crypto';
import { resolve } from 'node:path';
import type { Computer } from '../../ports/computer.ts';
import { serviceEnvironment } from '../process.ts';
import { createBridgeComputer } from './client.ts';

export type BrowserBridgeLauncher = (
  command: string,
  args: string[],
  options: SpawnOptionsWithoutStdio,
) => ChildProcessWithoutNullStreams;
export function browserNamespace(dataRoot: string) {
  return `sk-${createHash('sha256').update(resolve(dataRoot)).digest('hex').slice(0, 24)}`;
}

export function createContainerBrowserComputer(options: {
  dataRoot: string;
  container?: string;
  spawn?: BrowserBridgeLauncher;
  timeoutMs?: number;
  drainTimeoutMs?: number;
}): Computer {
  const container = options.container ?? 'nod-browser';
  if (!/^nod-browser(?:-[a-zA-Z0-9_-]+)?$/.test(container))
    throw new Error('BROWSER_CONTAINER must identify a Nod browser.');
  const launch = options.spawn ?? spawn;
  return createBridgeComputer({
    namespace: browserNamespace(options.dataRoot),
    timeoutMs: options.timeoutMs,
    drainTimeoutMs: options.drainTimeoutMs,
    launch: () =>
      launch('docker', ['exec', '-i', '--user', 'node', container, 'node', '/app/bridge.mjs'], {
        env: serviceEnvironment(),
        shell: false,
      }),
  });
}

import { posix, resolve } from 'node:path';
import { randomUUID } from 'node:crypto';
import type { ConnectedCli, Workspace } from '../../ports/computer.ts';
import { threadIdentity } from '../../ports/thread-identity.ts';
import {
  runWorkspaceCommand,
  WorkspaceCommandError,
  type WorkspaceCommandLauncher,
} from './command.ts';

export function workspaceFile(id: string, path: string): string {
  const base = `/workspace/${threadIdentity(id)}`;
  if (!path || path.includes('\0') || path.includes('\\'))
    throw new Error('A workspace file path is required.');
  const full = posix.resolve(base, path);
  if (full !== base && !full.startsWith(base + '/'))
    throw new Error('Files must stay within the task workspace.');
  return full;
}

const artifactChunk = 8 * 1024 * 1024;

export const artifactReadProgram = `import os,sys,json,stat
r=json.load(sys.stdin)
fds=[]
try:
 limit=int(r['maxBytes'])
 offset=int(r['offset'])
 if limit<1 or offset<0: raise ValueError()
 parts=r['path'].split('/')
 if not parts or any(p in ['', '.', '..'] for p in parts): raise ValueError()
 fd=os.open(r['base'],os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)
 fds.append(fd)
 for part in parts[:-1]:
  fd=os.open(part,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW,dir_fd=fd)
  fds.append(fd)
 fd=os.open(parts[-1],os.O_RDONLY|os.O_NOFOLLOW|os.O_NONBLOCK,dir_fd=fd)
 fds.append(fd)
 info=os.fstat(fd)
 if not stat.S_ISREG(info.st_mode) or info.st_size>limit or offset>info.st_size: raise ValueError()
 identity='%d:%d:%d:%d:%d'%(info.st_dev,info.st_ino,info.st_size,info.st_mtime_ns,info.st_ctime_ns)
 if r.get('identity') not in (None,identity): raise ValueError()
 want=min(${artifactChunk},info.st_size-offset)
 data=bytearray()
 while len(data)<want:
  chunk=os.pread(fd,want-len(data),offset+len(data))
  if not chunk: raise ValueError()
  data.extend(chunk)
 sys.stdout.buffer.write(identity.encode()+b'\\n'+data)
except Exception:
 sys.exit(1)
finally:
 for fd in reversed(fds): os.close(fd)
`;

export const artifactWriteProgram = `import os,sys,json,stat,base64
r=json.load(sys.stdin)
fds=[]
try:
 parts=r['path'].split('/')
 if not parts or any(p in ['', '.', '..'] for p in parts): raise ValueError()
 temporary=r['temporary']
 if not temporary.startswith('.nod-upload-') or '/' in temporary: raise ValueError()
 fd=os.open(r['base'],os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW)
 fds.append(fd)
 for part in parts[:-1]:
  try: os.mkdir(part,mode=0o700,dir_fd=fd)
  except FileExistsError: pass
  fd=os.open(part,os.O_RDONLY|os.O_DIRECTORY|os.O_NOFOLLOW,dir_fd=fd)
  fds.append(fd)
 if r.get('remove'):
  try: os.unlink(temporary,dir_fd=fd)
  except FileNotFoundError: pass
 else:
  offset=int(r['offset'])
  data=base64.b64decode(r['data'],validate=True)
  if offset<0 or len(data)>524288: raise ValueError()
  flags=os.O_WRONLY|os.O_NOFOLLOW|os.O_NONBLOCK
  flags=flags|(os.O_CREAT|os.O_EXCL if offset==0 else os.O_APPEND)
  file=os.open(temporary,flags,mode=0o600,dir_fd=fd)
  fds.append(file)
  info=os.fstat(file)
  if not stat.S_ISREG(info.st_mode) or info.st_size!=offset: raise ValueError()
  while data:
   written=os.write(file,data)
   if written<1: raise ValueError()
   data=data[written:]
  if r['done']:
   os.fsync(file)
   os.replace(temporary,parts[-1],src_dir_fd=fd,dst_dir_fd=fd)
   os.fsync(fd)
except Exception:
 sys.exit(1)
finally:
 for fd in reversed(fds): os.close(fd)
`;

export function createDockerWorkspace(options: {
  container: string;
  workspaceRoot: string;
  spawn?: WorkspaceCommandLauncher;
}): Workspace {
  return createCommandWorkspace({
    workspaceRoot: options.workspaceRoot,
    instructions:
      'Installed: Node, Python (pypdf, pdfplumber, pillow_heif, openpyxl, python-docx, python-pptx), LibreOffice (soffice), ffmpeg, yt-dlp, poppler-utils, qpdf, Ghostscript, Tesseract OCR, git, curl, ripgrep, jq and pipx. Install trusted Python libraries with pip install <package>, trusted CLIs with npm install -g <package> or pipx install <package>; /home/node persists across tasks and restarts. You have no sudo or display, so use a CLI or a web app in the browser, and IPv4 for internet access. Keep outputs in this workspace and never install on the owner\u2019s device.',
    runCommand: (id, args, input) =>
      runWorkspaceCommand({
        container: options.container,
        threadId: id,
        args,
        ...input,
        spawn: options.spawn,
      }),
    runConnectedCommand: (id, args, input) =>
      runWorkspaceCommand({
        container: options.container,
        threadId: id,
        args,
        ...input,
        spawn: options.spawn,
      }),
  });
}

type CommandInput = {
  input?: string;
  environment?: Record<string, string>;
  signal?: AbortSignal;
  timeoutMs?: number;
  maxBytes?: number;
  onData?(chunk: Buffer): void;
  session?: boolean;
};
type CommandResult = { stdout: Buffer; stderr: Buffer; exitCode: number };

export function createCommandWorkspace(options: {
  workspaceRoot: string;
  instructions: string;
  runCommand(id: string, args: string[], input: CommandInput): Promise<CommandResult>;
  runConnectedCommand?(
    id: string,
    args: string[],
    input: CommandInput & { environment: Record<string, string>; cli: ConnectedCli },
  ): Promise<CommandResult>;
}): Workspace {
  let unavailable: string | undefined;
  let disposed = false;
  let lifecycle = new AbortController();
  let recovery: Promise<string | undefined> | undefined;
  const pending = new Set<Promise<unknown>>();
  function recover(error: WorkspaceCommandError) {
    const current = (async (previous) => {
      lifecycle.abort();
      await Promise.allSettled([previous, ...pending]);
      try {
        if (!error.stop) throw new Error('Its processes cannot be checked.');
        await error.stop();
        lifecycle = new AbortController();
      } catch (cause) {
        unavailable ??= `${error.message} Nod could not confirm that its processes stopped: ${cause instanceof Error ? cause.message : String(cause)} Restart Nod before continuing.`;
        return unavailable;
      }
    })(recovery);
    recovery = current;
    void current.finally(() => {
      if (recovery === current) recovery = undefined;
    });
    return current;
  }
  async function supervise(
    run: (signal: AbortSignal) => Promise<CommandResult>,
    signal?: AbortSignal,
  ) {
    while (recovery) await recovery;
    if (disposed) throw new Error('The workspace is unavailable. Restart Nod before continuing.');
    if (unavailable) throw new Error(unavailable);
    const operation = run(signal ? AbortSignal.any([signal, lifecycle.signal]) : lifecycle.signal);
    pending.add(operation);
    try {
      return await operation;
    } catch (error) {
      if (!(error instanceof WorkspaceCommandError && error.uncertain)) throw error;
      throw new WorkspaceCommandError(
        true,
        (await recover(error)) ??
          `${error.message} Its processes are confirmed stopped and its result is unknown. The workspace is available.`,
      );
    } finally {
      pending.delete(operation);
    }
  }
  const command = (id: string, args: string[], input: CommandInput = {}) =>
    supervise((signal) => options.runCommand(id, args, { ...input, signal }), input.signal);
  async function helper(id: string, program: string, request: unknown, input: CommandInput) {
    const result = await command(id, ['/usr/bin/python3', '-I', '-c', program], {
      ...input,
      input: JSON.stringify(request),
    });
    if (result.exitCode) throw new Error('The workspace file operation failed.');
    return result;
  }
  return {
    connectedCliAvailable: Boolean(options.runConnectedCommand),
    dispose: async () => {
      disposed = true;
      lifecycle.abort();
      await Promise.allSettled([...pending]);
    },
    async writeArtifact(id, path, bytes, signal) {
      threadIdentity(id);
      if (!bytes.byteLength) throw new Error('A file needs at least one byte.');
      const base = `/workspace/${id}`;
      const target = posix.relative(base, workspaceFile(id, path));
      const temporary = `.nod-upload-${randomUUID()}`;
      try {
        for (let offset = 0; offset < bytes.byteLength; offset += 512 * 1024) {
          const chunk = bytes.subarray(offset, offset + 512 * 1024);
          await helper(
            id,
            artifactWriteProgram,
            {
              base,
              path: target,
              temporary,
              offset,
              data: Buffer.from(chunk).toString('base64'),
              done: offset + chunk.byteLength === bytes.byteLength,
            },
            { maxBytes: 1024, signal },
          );
        }
      } catch (error) {
        await helper(
          id,
          artifactWriteProgram,
          { base, path: target, temporary, remove: true },
          { maxBytes: 1024 },
        ).catch(() => {});
        throw error;
      }
    },
    async readArtifact(id, path, maxBytes) {
      threadIdentity(id);
      if (!Number.isSafeInteger(maxBytes) || maxBytes < 1)
        throw new Error('The artifact size limit is invalid.');
      const base = `/workspace/${id}`;
      const target = posix.relative(base, workspaceFile(id, path));
      const chunks: Buffer[] = [];
      let identity: string | undefined;
      let offset = 0;
      let size = 0;
      do {
        const { stdout } = await helper(
          id,
          artifactReadProgram,
          { base, path: target, maxBytes, offset, identity },
          { maxBytes: artifactChunk + 1024 },
        );
        const line = stdout.indexOf(10);
        const header = stdout.subarray(0, Math.max(line, 0)).toString();
        if (line < 0 || line > 1024 || (identity !== undefined && header !== identity))
          throw new Error('The workspace file changed while it was read.');
        identity = header;
        size = Number(header.split(':')[2]);
        const data = stdout.subarray(line + 1);
        if (
          !Number.isSafeInteger(size) ||
          size < 0 ||
          size > maxBytes ||
          data.byteLength > Math.min(artifactChunk, size - offset, maxBytes - offset) ||
          (!data.byteLength && offset < size)
        )
          throw new Error('The workspace file operation failed.');
        chunks.push(data);
        offset += data.byteLength;
      } while (offset < size);
      if (offset !== size) throw new Error('The workspace file operation failed.');
      return Buffer.concat(chunks, offset);
    },
    open(input) {
      const id = threadIdentity(input.threadId);
      if (resolve(input.workspacePath) !== resolve(options.workspaceRoot, id))
        throw new Error('The task workspace does not match its configured root.');
      const connected = options.runConnectedCommand;
      return {
        path: `/workspace/${id}`,
        instructions: options.instructions,
        async exec(script, { input: stdin, signal, timeoutMs = 600_000, onData, notices } = {}) {
          const result = await command(
            id,
            [
              '/bin/bash',
              '--noprofile',
              '--norc',
              '-p',
              '-c',
              `nod_workspace_path=$PATH\nexport PATH='/usr/local/sbin:/usr/local/bin:/usr/sbin:/usr/bin:/sbin:/bin'\n${script}`,
            ],
            {
              input: stdin,
              signal: signal ? AbortSignal.any([signal, input.signal]) : input.signal,
              timeoutMs: Math.max(1000, timeoutMs),
              onData: onData ?? (() => {}),
              session: notices,
            },
          );
          return { exitCode: result.exitCode };
        },
        ...(connected
          ? {
              runConnectedCli: async (
                cli: ConnectedCli,
                args: string[],
                environment: Record<string, string>,
                timeoutSeconds = 3540,
              ) => {
                const result = await supervise(
                  (signal) =>
                    connected(id, args, {
                      cli,
                      environment,
                      signal,
                      timeoutMs: Math.max(1, timeoutSeconds) * 1000,
                    }),
                  input.signal,
                );
                return {
                  exitCode: result.exitCode,
                  output: Buffer.concat([result.stdout, result.stderr]).toString('utf8'),
                  stdout: result.stdout.toString('utf8'),
                  stderr: result.stderr.toString('utf8'),
                };
              },
            }
          : {}),
      };
    },
  };
}

{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://agent-plugins.org/schemas/1.0.0/mcp.schema.json",
  "title": "Agent Plugins MCP Configuration",
  "description": "Machine-readable schema for mcp.json in Agent Plugins 1.0.0. The Agent Plugins specification defines additional semantic and operational requirements.",
  "type": "object",
