import assert from 'node:assert/strict';
import { execFile } from 'node:child_process';
import { readFile, writeFile, mkdir } from 'node:fs/promises';
import { resolve } from 'node:path';
import { promisify } from 'node:util';

const exec = promisify(execFile);
const directory = resolve(process.argv[2] ?? '.local/nod-media');
const destination = resolve(process.argv[3] ?? 'docs/src/assets/video');
const scenes = JSON.parse(await readFile(`${directory}/scenes.json`, 'utf8'));
await mkdir(destination, { recursive: true });
const rate = 48000;
const silence = (seconds) => Buffer.alloc(Math.round(seconds * rate) * 2);
const chunks = [];
const cues = [];
let samples = 0;
for (const [index, scene] of scenes.entries()) {
  if (index) {
    const previous = chunks.pop();
    chunks.push(previous.subarray(0, previous.length - Math.round(0.45 * rate) * 2));
    samples -= Math.round(0.45 * rate);
  }
  scene.start = samples / rate;
  chunks.push(silence(0.6));
  samples += 0.6 * rate;
  for (const [part, sentence] of scene.text.split(/(?<=[.!?])\s+/).entries()) {
    const path = `${directory}/speech-${index}-${part}.aiff`;
    await exec('say', ['-v', 'Daniel', '-r', '178', '-o', path, sentence]);
    const { stdout } = await exec(
      'ffmpeg',
      ['-v', 'error', '-i', path, '-ar', String(rate), '-ac', '1', '-f', 's16le', '-'],
      { encoding: 'buffer', maxBuffer: 20_000_000 },
    );
    assert(stdout.length > 0 && stdout.length % 2 === 0);
    cues.push({ start: samples / rate, end: (samples + stdout.length / 2) / rate, text: sentence });
    chunks.push(stdout, silence(0.16));
    samples += stdout.length / 2 + Math.round(0.16 * rate);
  }
  chunks.push(silence(0.8));
  samples += 0.8 * rate;
  scene.duration = samples / rate - scene.start;
}
await writeFile(`${directory}/speech.pcm`, Buffer.concat(chunks));
await exec('ffmpeg', [
  '-v',
  'error',
  '-y',
  '-f',
  's16le',
  '-ar',
  String(rate),
  '-ac',
  '1',
  '-i',
  `${directory}/speech.pcm`,
  '-af',
  'loudnorm=I=-16:TP=-1.5:LRA=11',
  '-ar',
  String(rate),
  `${directory}/speech.wav`,
]);
const input = scenes.flatMap((scene, index) => [
  '-loop',
  '1',
  '-framerate',
  '30',
  '-t',
  String(scene.duration),
  '-i',
  `${directory}/scene-${index}.png`,
]);
const filters = scenes.map((_, index) => `[${index}:v]settb=AVTB,format=yuv420p[v${index}]`);
for (let i = 1; i < scenes.length; i++)
  filters.push(
    `[${i === 1 ? 'v0' : `mix${i - 1}`}][v${i}]xfade=transition=fade:duration=0.45:offset=${scenes[i].start}[mix${i}]`,
  );
await exec(
  'ffmpeg',
  [
    '-hide_banner',
    '-loglevel',
    'warning',
    '-y',
    '-filter_complex_threads',
    '1',
    ...input,
    '-i',
    `${directory}/speech.wav`,
    '-filter_complex',
    filters.join(';'),
    '-map',
    `[mix${scenes.length - 1}]`,
    '-map',
    `${scenes.length}:a`,
    '-c:v',
    'libx264',
    '-preset',
    'medium',
    '-crf',
    '20',
    '-pix_fmt',
    'yuv420p',
    '-c:a',
    'aac',
    '-b:a',
    '96k',
    '-movflags',
    '+faststart',
    '-shortest',
    `${destination}/trust-layer.mp4`,
  ],
  { maxBuffer: 5_000_000 },
);
const timestamp = (seconds) => {
  const value = Math.round(seconds * 1000);
  return `${String(Math.floor(value / 3600000)).padStart(2, '0')}:${String(Math.floor(value / 60000) % 60).padStart(2, '0')}:${String(Math.floor(value / 1000) % 60).padStart(2, '0')}.${String(value % 1000).padStart(3, '0')}`;
};
await writeFile(
  `${destination}/trust-layer.vtt`,
  `WEBVTT\n\n${cues.map((cue, index) => `${index + 1}\n${timestamp(cue.start)} --> ${timestamp(cue.end)}\n${cue.text}\n`).join('\n')}`,
);
await exec('ffmpeg', [
  '-v',
  'error',
  '-y',
  '-ss',
  String(scenes[1].start + 1),
  '-i',
  `${destination}/trust-layer.mp4`,
  '-frames:v',
  '1',
  '-q:v',
  '3',
  `${destination}/trust-layer-poster.jpg`,
]);
await writeFile(
  `${directory}/timing.json`,
  JSON.stringify({ scenes, cues, duration: samples / rate }, null, 2),
);
console.log(
  `Created a ${Math.round(samples / rate)} second tour with ${cues.length} caption cues.`,
);

import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createAgentBrowserComputer } from '../src/providers/agent-browser/index.ts';
import { startContainerBrowserWorker } from '../src/providers/container-browser/worker.ts';
import { containerBrowserOptions } from '../src/providers/container-browser/config.ts';
import { createFixtureProxy } from './e2e-fixtures.ts';

const worker = await startContainerBrowserWorker({
  createComputer: async (dataRoot) => {
    const proxy = await createFixtureProxy(
      join(dataRoot, 'certificate'),
      (kind, fields = {}) => {
        process.stdout.write(JSON.stringify({ kind, ...fields }) + '\n');
      },
      undefined,
      fileURLToPath(new URL('./signup-operator.json', import.meta.url)),
    );
    const computer = createAgentBrowserComputer({
      ...containerBrowserOptions(dataRoot),
      run: proxy.run,
    });
    return {
      ...computer,
      dispose: async () => {
        try {
          await computer.dispose?.();
        } finally {
          await proxy.close();
        }
      },
    };
  },
});
const stop = () => void worker.close().finally(() => process.exit(0));
process.once('SIGTERM', stop);
process.once('SIGINT', stop);

import { writeFile } from 'node:fs/promises';
import { basename } from 'node:path';
import { JSDOM } from 'jsdom';
import { fakeDevtools } from './browser-fixture.ts';
import type { runProcess } from '../src/providers/process.ts';

class LoginPage {
  stage: 'identifier' | 'password' | 'otp' | 'complete' = 'identifier';
  location = { origin: 'https://1.1.1.1', href: 'https://1.1.1.1/login' };
  dom = new JSDOM('', { url: this.location.href, runScripts: 'outside-only' });
  input!: HTMLInputElement;
  search!: HTMLInputElement;
  next!: HTMLButtonElement;
  entered: string[] = [];
  document = 'loader-0';
  isolated: Record<string, unknown> = {};
  focused?: HTMLInputElement;
  afterInspect?(expression: string): void;
  refs = new Map<string, Element>();
  constructor() {
    this.dom.window.HTMLElement.prototype.getClientRects = () => [{}] as unknown as DOMRectList;
    Object.defineProperty(this.dom.window.HTMLElement.prototype, 'innerText', {
      get() {
        return this.textContent;
      },
    });
    this.render();
  }
  render() {
    this.dom.window.document.execCommand = (command: string, _ui?: boolean, value?: string) => {
      const node = this.dom.window.document.activeElement as HTMLInputElement;
      if (!node || !('value' in node)) return false;
      if (command === 'delete') node.value = '';
      if (command === 'insertText') {
        node.value += value ?? '';
        node.dispatchEvent(new this.dom.window.Event('input', { bubbles: true }));
      }
      return true;
    };
    this.dom.window.document.body.innerHTML = `<h1>Sign in ${this.stage}</h1><form><label>Account<input id="account"></label><button type="button" disabled>Next</button></form><input id="search" aria-label="Search"><div id="echo"></div>`;
    this.input = this.dom.window.document.querySelector('#account')!;
    this.input.name = this.stage;
    this.input.autocomplete =
      this.stage === 'identifier'
        ? 'username'
        : this.stage === 'otp'
          ? 'one-time-code'
          : 'current-password';
    this.input.type = this.stage === 'password' ? 'password' : 'text';
    this.search = this.dom.window.document.querySelector('#search')!;
    this.next = this.dom.window.document.querySelector('button')!;
    this.dom.window.document.querySelector('#echo')!.textContent = this.entered.join(' ');
    this.input.addEventListener('input', () => {
      this.next.disabled = false;
    });
    this.next.addEventListener('click', () => {
      this.entered.push(this.input.value);
      this.stage =
        this.stage === 'identifier' ? 'password' : this.stage === 'password' ? 'otp' : 'complete';
      this.render();
    });
    if (this.stage === 'complete') this.input.remove();
  }
  nodes(selector: string): Element[] {
    if (selector.startsWith('@')) {
      const node = this.refs.get(selector);
      return node?.isConnected ? [node] : [];
    }
    return [...this.dom.window.document.querySelectorAll(selector)];
  }
  snapshot() {
    const lines = [this.text()];
    const refs: Record<string, { role: string; name: string }> = {};
    for (const node of this.dom.window.document.querySelectorAll('input,button')) {
      let ref = [...this.refs].find(([, element]) => element === node)?.[0];
      if (!ref) {
        ref = `@e${this.refs.size + 1}`;
        this.refs.set(ref, node);
      }
      const role = node.tagName === 'INPUT' ? 'textbox' : 'button';
      const name = node.getAttribute('aria-label') ?? node.id ?? 'Next';
      refs[ref.slice(1)] = { role, name };
      lines.push(
        `- ${role} "${name}" [ref=${ref.slice(1)}]${node.tagName === 'INPUT' ? `: ${(node as HTMLInputElement).value}` : ''}`,
      );
    }
    return { snapshot: lines.join('\n'), refs };
  }
  text() {
    return this.dom.window.document.body.textContent ?? '';
  }
  screen() {
    const echo = this.dom.window.document.querySelector<HTMLElement>('#echo')!;
    const style = this.dom.window.getComputedStyle(echo);
    return `Screen ${this.stage} ${style.color === 'transparent' || style.opacity === '0' || style.visibility === 'hidden' ? '[redacted]' : echo.textContent}`;
  }
  async evaluate(script: string) {
    this.dom.reconfigure({ url: this.location.href });
    return this.dom.window.eval(script) as unknown;
  }
}

export function stagedLoginBrowser() {
  const pages = new Map<string, LoginPage>();
  const inspectors = new Map<string, Awaited<ReturnType<typeof fakeDevtools>>>();
  let documents = 0;
  const run: typeof runProcess = async (_executable, args, options) => {
    const id = basename(args[args.indexOf('--profile') + 1]);
    let page = pages.get(id);
    if (!page) {
      page = new LoginPage();
      pages.set(id, page);
      page.document = `loader-${++documents}`;
    }
    const command = args.slice(args.indexOf('--idle-timeout') + 2);
    let data: Record<string, unknown> = {};
    if (command[0] === 'get' && command[1] === 'cdp-url' && !inspectors.has(id)) {
      const target = page;
      const inspector = await fakeDevtools({
        get document() {
          return target.document;
        },
        get frames() {
          return [{ id: 'main', session: 'page', origin: target.location.origin }];
        },
        frameOf: {},
        values: new Map(),
        evaluate: (expression) => {
          const value = new Function(
            'document',
            'globalThis',
            'Event',
            'NodeFilter',
            'getComputedStyle',
            'MutationObserver',
            `return ${expression}`,
          )(
            target.dom.window.document,
            target.isolated,
            target.dom.window.Event,
            target.dom.window.NodeFilter,
            target.dom.window.getComputedStyle.bind(target.dom.window),
            target.dom.window.MutationObserver,
          );
          target.afterInspect?.(expression);
          return value;
        },
      });
      inspectors.set(id, inspector);
    }
    if (command[0] === 'is' && command[1] === 'enabled') {
      const node = page.nodes(command[2])[0];
      data = { enabled: Boolean(node && !node.matches(':disabled')) };
    }
    if (command[0] === 'focus')
      page.nodes(command[1])[0]?.dispatchEvent(new page.dom.window.Event('focus'));
    if (command[0] === 'focus') (page.nodes(command[1])[0] as HTMLElement | undefined)?.focus();
    if (command[0] === 'press' && command[1] === 'Enter') page.next.click();
    if (command[0] === 'reload') {
      page.dom.window.close();
      page.dom = new JSDOM('', { url: page.location.href, runScripts: 'outside-only' });
      page.isolated = {};
      page.document = `loader-${++documents}`;
      page.render();
    }
    if (command[0] === 'get')
      data =
        command[1] === 'url'
          ? { url: page.location.href }
          : command[1] === 'cdp-url'
            ? { cdpUrl: inspectors.get(id)!.url }
            : { value: page.nodes(command[2])[0]?.getAttribute(command[3]) ?? null };
    if (command[0] === 'eval') data = { result: await page.evaluate(options?.input ?? '') };
    if (command[0] === 'click') {
      const node = page.nodes(command[1])[0] as HTMLElement | undefined;
      node?.focus();
      node?.click();
    }
    if (command[0] === 'keyboard' && command[1] === 'type') {
      const node = page.dom.window.document.activeElement;
      if (node instanceof page.dom.window.HTMLInputElement) {
        node.value += command[2];
        node.dispatchEvent(new page.dom.window.Event('input', { bubbles: true }));
      }
    }
    if (command[0] === 'fill') {
      const node = page.nodes(command[1])[0] as HTMLInputElement | undefined;
      if (node) {
        page.focused = node;
        node.value = command[2];
        node.dispatchEvent(new page.dom.window.Event('input', { bubbles: true }));
      }
    }
    if (command[0] === 'press' && page.focused && command[1].length === 1) {
      page.focused.value += command[1];
      page.focused.dispatchEvent(new page.dom.window.Event('input', { bubbles: true }));
    }
    if (command[0] === 'snapshot') data = page.snapshot();
    if (command[0] === 'screenshot') await writeFile(command[1], page.screen());
    if (command[0] === 'close') {
      page.dom.window.close();
      pages.delete(id);
      await inspectors.get(id)?.close();
      inspectors.delete(id);
    }
    return { stdout: JSON.stringify({ success: true, data }), stderr: '', exitCode: 0 };
  };
  return { run, pages };
}

package main

import (
	"os"
	"os/exec"
	"path/filepath"
	"regexp"
	"syscall"
)

func main() {
	distribution := os.Getenv("NOD_WSL_DISTRIBUTION")
	if !regexp.MustCompile(`^nod-[a-f0-9]{12}$`).MatchString(distribution) {
		os.Exit(64)
	}
	system := os.Getenv("SYSTEMROOT")
	if !filepath.IsAbs(system) {
		os.Exit(64)
	}
	args := append([]string{"--distribution", distribution, "--user", "root", "--exec", "/usr/local/bin/nod-docker"}, os.Args[1:]...)
	command := exec.Command(filepath.Join(system, "System32", "wsl.exe"), args...)
	for _, key := range []string{"SYSTEMROOT", "USERPROFILE", "LOCALAPPDATA", "TEMP", "TMP"} {
		if value := os.Getenv(key); value != "" {
			command.Env = append(command.Env, key+"="+value)
		}
	}
	if value := os.Getenv("POSTGRES_PASSWORD"); value != "" {
		command.Env = append(command.Env, "POSTGRES_PASSWORD="+value, "WSLENV=POSTGRES_PASSWORD")
	}
	command.SysProcAttr = &syscall.SysProcAttr{HideWindow: true}
	command.Stdin, command.Stdout, command.Stderr = os.Stdin, os.Stdout, os.Stderr
	if error := command.Run(); error != nil {
		if exit, ok := error.(*exec.ExitError); ok {
			os.Exit(exit.ExitCode())
		}
		os.Exit(127)
	}
}

