import dns from 'node:dns';
import http from 'node:http';
import https from 'node:https';
import { syncBuiltinESMExports } from 'node:module';

const publicAddress = '93.184.216.34';

export function routeFixtureHosts(hosts: string[], origin: string) {
  const fixture = new Set(hosts.map((host) => host.toLowerCase()));
  const lookup = dns.promises.lookup;
  const realFetch = globalThis.fetch;
  const realRequest = https.request;
  https.request = ((...args: Parameters<typeof https.request>) => {
    const [first, second, third] = args as [unknown, unknown, unknown];
    const target = typeof first === 'string' || first instanceof URL ? new URL(first) : undefined;
    if (!target || !fixture.has(target.hostname.toLowerCase()))
      return (realRequest as (...input: unknown[]) => ReturnType<typeof https.request>)(...args);
    const options = (typeof second === 'object' && second ? second : {}) as https.RequestOptions;
    const callback = (typeof second === 'function' ? second : third) as
      ((response: http.IncomingMessage) => void) | undefined;
    const { lookup: _lookup, agent: _agent, ...rest } = options;
    const local = new URL(`${target.pathname}${target.search}`, origin);
    return http.request(
      local,
      {
        ...rest,
        headers: { ...(rest.headers as Record<string, string>), 'x-fixture-host': target.host },
      },
      callback,
    );
  }) as typeof https.request;
  dns.promises.lookup = ((hostname: string, options?: dns.LookupOptions) =>
    fixture.has(hostname.toLowerCase())
      ? Promise.resolve(
          options?.all
            ? [{ address: publicAddress, family: 4 }]
            : { address: publicAddress, family: 4 },
        )
      : lookup(hostname, options ?? {})) as typeof dns.promises.lookup;
  syncBuiltinESMExports();
  globalThis.fetch = ((input: RequestInfo | URL, init?: RequestInit) => {
    const request = input instanceof Request ? input : undefined;
    const url = new URL(request?.url ?? String(input));
    if (!fixture.has(url.hostname.toLowerCase())) return realFetch(input, init);
    const { dispatcher: _dispatcher, ...options } = (init ?? {}) as RequestInit & {
      dispatcher?: unknown;
    };
    const target = new URL(`${url.pathname}${url.search}`, origin);
    if (request) {
      const routed = new Request(target, new Request(request, options));
      routed.headers.set('x-fixture-host', url.host);
      return realFetch(routed);
    }
    const headers = new Headers(options.headers);
    headers.set('x-fixture-host', url.host);
    return realFetch(target, { ...options, headers });
  }) as typeof fetch;
  return () => {
    dns.promises.lookup = lookup;
    globalThis.fetch = realFetch;
    https.request = realRequest;
    syncBuiltinESMExports();
  };
}

import { createHash, X509Certificate } from 'node:crypto';
import { mkdir, readFile } from 'node:fs/promises';
import { createServer, request as httpRequest, type RequestListener } from 'node:http';
import { createServer as createHttpsServer } from 'node:https';
import type { AddressInfo, Socket } from 'node:net';
import { join } from 'node:path';
import { runProcess } from '../../../src/providers/process.ts';

export async function createFixtureProxy(
  directory: string,
  hosts: string[],
  handler: RequestListener,
  hermetic = false,
) {
  await mkdir(directory, { recursive: true, mode: 0o700 });
  const key = join(directory, 'fixture.key');
  const cert = join(directory, 'fixture.crt');
  const generated = await runProcess('openssl', [
    'req',
    '-x509',
    '-newkey',
    'rsa:2048',
    '-nodes',
    '-keyout',
    key,
    '-out',
    cert,
    '-days',
    '1',
    '-subj',
    `/CN=${hosts[0]}`,
    '-addext',
    `subjectAltName=${hosts.map((host) => `DNS:${host}`).join(',')}`,
  ]);
  if (generated.exitCode) throw new Error('Could not create the fixture certificate.');
  const certificate = await readFile(cert);
  const fingerprint = createHash('sha256')
    .update(new X509Certificate(certificate).publicKey.export({ format: 'der', type: 'spki' }))
    .digest('base64');
  const tls = { key: await readFile(key), cert: certificate };
  const secure = new Set<ReturnType<typeof createHttpsServer>>();
  const sockets = new Set<Socket>();
  const track = (socket: Socket) => {
    sockets.add(socket);
    socket.once('close', () => sockets.delete(socket));
  };
  const proxies = new Map<string, Promise<string>>();
  const servers = new Set<ReturnType<typeof createServer>>();
  function upstreamProxy(value: string, browser: string) {
    const upstream = new URL(value);
    if (upstream.protocol !== 'http:' || upstream.hostname !== '127.0.0.1')
      throw new Error('The fixture proxy requires the production loopback guard.');
    let ready = proxies.get(upstream.href);
    if (ready) return ready;
    const https = createHttpsServer(tls, (request, response) => {
      request.headers['x-fixture-browser'] = browser;
      handler(request, response);
    });
    secure.add(https);
    const proxy = createServer((request, response) => {
      if (hermetic) return void response.writeHead(hermetic ? 403 : 503).end();
      const forward = httpRequest(
        upstream,
        { method: request.method, path: request.url, headers: request.headers },
        (result) => {
          response.writeHead(result.statusCode || 502, result.headers);
          result.pipe(response);
        },
      );
      forward.on('error', () => response.destroy());
      request.pipe(forward);
    });
    proxy.on('connection', track);
    proxy.on('connect', (request, socket, head) => {
      if (hosts.some((host) => request.url === `${host}:443`)) {
        socket.write('HTTP/1.1 200 Connection Established\r\n\r\n');
        if (head.length) socket.unshift(head);
        https.emit('connection', socket);
        return;
      }
      if (hermetic) return socket.destroy();
      const forward = httpRequest(upstream, {
        method: 'CONNECT',
        path: request.url,
        headers: { host: request.url || '' },
      });
      forward.on('socket', track);
      socket.on('close', () => forward.destroy());
      socket.on('error', () => forward.destroy());
      forward.on('connect', (response, remote, remoteHead) => {
        socket.write(
          `HTTP/1.1 ${response.statusCode || 502} ${response.statusMessage || ''}\r\n\r\n`,
        );
        if (response.statusCode !== 200) {
          remote.destroy();
          socket.destroy();
          return;
        }
        if (remoteHead.length) socket.write(remoteHead);
        if (head.length) remote.write(head);
        remote.on('error', () => socket.destroy());
        remote.on('close', () => {
          if (!remote.readableEnded) socket.destroy();
        });
        socket.on('error', () => remote.destroy());
        socket.on('close', () => remote.destroy());
        remote.pipe(socket).pipe(remote);
      });
      forward.on('error', () => socket.destroy());
      forward.end();
    });
    servers.add(proxy);
    ready = new Promise<string>((resolve, reject) => {
      proxy.once('error', reject);
      proxy.listen(0, '127.0.0.1', () =>
        resolve(`http://127.0.0.1:${(proxy.address() as AddressInfo).port}`),
      );
    });
    proxies.set(upstream.href, ready);
    return ready;
  }
  return {
    run: (async (command, args, options) => {
      const values = [...args];
      const proxyIndex = values.indexOf('--proxy');
      if (proxyIndex >= 0) {
        const session = values.indexOf('--session');
        values[proxyIndex + 1] = await upstreamProxy(
          values[proxyIndex + 1],
          session >= 0 ? values[session + 1] : '',
        );
        const flags = values.indexOf('--args');
        if (flags < 0) throw new Error('Browser arguments were missing.');
        values[flags + 1] += `,--ignore-certificate-errors-spki-list=${fingerprint}`;
      }
      return runProcess(command, values, options);
    }) satisfies typeof runProcess,
    close: async () => {
      for (const socket of sockets) socket.destroy();
      await Promise.all(
        [...servers].map((server) => new Promise<void>((resolve) => server.close(() => resolve()))),
      );
      for (const server of secure) server.close();
    },
  };
}

import assert from 'node:assert/strict';
import { once } from 'node:events';
import { spawn } from 'node:child_process';
import { createServer } from 'node:http';
import { mkdtemp, readFile, rm, writeFile, mkdir, readdir } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { resolve, extname } from 'node:path';
import { build } from 'esbuild';

const output = resolve(process.argv[2] ?? '.local/nod-media');
await mkdir(output, { recursive: true });
await build({
  entryPoints: ['docs/media/trust-tour.tsx'],
  bundle: true,
  outfile: `${output}/tour.js`,
  jsx: 'automatic',
  loader: { '.woff2': 'file' },
  logLevel: 'warning',
  plugins: [
    {
      name: 'compiled-styles',
      setup(builder) {
        builder.onLoad({ filter: /\.css$/ }, () => ({ contents: '', loader: 'css' }));
      },
    },
  ],
});
const css = (await readdir('dist/web/assets')).find(
  (name) => name.startsWith('index-') && name.endsWith('.css'),
);
assert(css, 'Run pnpm run build before capture.');
await writeFile(
  `${output}/tour.css`,
  `${await readFile(`dist/web/assets/${css}`, 'utf8')}\n${await readFile('docs/media/trust-tour.css', 'utf8')}`,
);
const mime = {
  '.js': 'text/javascript',
  '.css': 'text/css',
  '.woff2': 'font/woff2',
  '.svg': 'image/svg+xml',
  '.png': 'image/png',
};
const server = createServer(async (request, response) => {
  try {
    const path = new URL(request.url, 'http://localhost').pathname;
    if (path === '/') {
      response.setHeader('Content-Type', 'text/html');
      response.end(
        '<!doctype html><html lang="en"><head><meta charset="utf-8"><link rel="stylesheet" href="/tour.css"></head><body><div id="root"></div><script src="/tour.js"></script></body></html>',
      );
      return;
    }
    const root = path.startsWith('/tour.') ? output : resolve('public');
    const file = resolve(root, `.${path}`);
    assert(file.startsWith(`${root}/`));
    response.setHeader('Content-Type', mime[extname(file)] ?? 'application/octet-stream');
    response.end(await readFile(file));
  } catch {
    response.writeHead(404).end();
  }
});
await new Promise((resolve) => server.listen(0, '127.0.0.1', resolve));
const profile = await mkdtemp(`${tmpdir()}/nod-media-chrome-`);
let chrome;
let socket;
try {
  chrome = spawn(
    process.env.NOD_MEDIA_CHROME ?? '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    [
      '--headless=new',
      '--hide-scrollbars',
      '--no-first-run',
      '--no-default-browser-check',
      '--remote-debugging-port=0',
      `--user-data-dir=${profile}`,
      'about:blank',
    ],
    { stdio: 'ignore' },
  );
  await once(chrome, 'spawn');
  let port;
  for (let i = 0; i < 100; i++) {
    try {
      port = Number((await readFile(`${profile}/DevToolsActivePort`, 'utf8')).split('\n')[0]);
      break;
    } catch {
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
  }
  assert(port, 'Chrome did not start.');
  const pages = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
  socket = new WebSocket(pages.find((page) => page.type === 'page').webSocketDebuggerUrl);
  await new Promise((resolve, reject) => {
    socket.onopen = resolve;
    socket.onerror = reject;
  });
  let id = 0;
  const pending = new Map();
  const errors = [];
  socket.onmessage = ({ data }) => {
    const message = JSON.parse(data);
    if (message.method === 'Runtime.exceptionThrown')
      errors.push(
        message.params.exceptionDetails.exception?.description ??
          message.params.exceptionDetails.text,
      );
    pending.get(message.id)?.(message);
  };
  const send = async (method, params = {}) => {
    const current = ++id;
    const result = await Promise.race([
      new Promise((resolve) => {
        pending.set(current, resolve);
        socket.send(JSON.stringify({ id: current, method, params }));
      }),
      new Promise((_, reject) =>
        setTimeout(() => reject(new Error(`${method} timed out.`)), 30000).unref(),
      ),
    ]);
    pending.delete(current);
    assert(!result.error, result.error?.message);
    return result.result;
  };
  const evaluate = async (expression) => {
    const result = await send('Runtime.evaluate', {
      expression,
      awaitPromise: true,
      returnByValue: true,
    });
    assert(!result.exceptionDetails, result.exceptionDetails?.exception?.description);
    return result.result.value;
  };
  await send('Runtime.enable');
  await send('Page.enable');
  await send('Emulation.setDeviceMetricsOverride', {
    width: 1920,
    height: 1080,
    deviceScaleFactor: 1,
    mobile: false,
  });
  await send('Page.navigate', { url: `http://127.0.0.1:${server.address().port}/` });
  for (let i = 0; i < 100 && !(await evaluate('window.mediaReady === true')); i++)
    await new Promise((resolve) => setTimeout(resolve, 100));
  assert(await evaluate('window.mediaReady === true'), 'The media page did not load.');
  await evaluate('document.fonts.ready');
  const scenes = await evaluate('window.mediaScenes');
  for (let i = 0; i < scenes.length; i++) {
    await evaluate(`window.renderMedia(${i})`);
    await new Promise((resolve) => setTimeout(resolve, 450));
    await evaluate('document.activeElement?.blur()');
    assert(!(await evaluate('/otto/i.test(document.body.innerText)')), 'An old name remains.');
    if (i === 1)
      assert.equal(
        await evaluate('getComputedStyle(document.querySelector(".message-text")).fontSize'),
        '22px',
      );
    if (scenes[i].view === 'usage')
      assert(
        await evaluate('document.body.innerText.includes("Nod spent")'),
        'Usage did not load.',
      );
    const screenshot = await send('Page.captureScreenshot', {
      format: 'png',
      captureBeyondViewport: false,
    });
    await writeFile(`${output}/scene-${i}.png`, Buffer.from(screenshot.data, 'base64'));
  }
  await mkdir(`${output}/screens`, { recursive: true });
  for (const [name, width, height, kind, theme, limit] of [
    ['card-usage-light', 660, 495, 'usage-card', 'light'],
    ['card-usage-dark', 660, 495, 'usage-card', 'dark'],
    ['usage-light', 1000, 680, 'usage', 'light'],
    ['vault-light', 1000, 680, 'vault', 'light'],
    ['usage-task-limit', 1000, 680, 'usage-limit', 'light', true],
    ['verify-code-page', 800, 450, 'code', 'light'],
  ]) {
    await send('Emulation.setDeviceMetricsOverride', {
      width,
      height,
      deviceScaleFactor: 2,
      mobile: false,
    });
    await evaluate(
      `document.documentElement.dataset.theme=${JSON.stringify(theme)}; window.renderMedia(0,${JSON.stringify(kind)})`,
    );
    await new Promise((resolve) => setTimeout(resolve, 500));
    if (limit) {
      await evaluate(
        `Array.from(document.querySelectorAll('button')).find(button => button.textContent.includes('$5')).click()`,
      );
      await new Promise((resolve) => setTimeout(resolve, 400));
    }
    await evaluate('document.activeElement?.blur()');
    assert(
      !(await evaluate(
        '/could not be opened|No media fixture|Opening your form/.test(document.body.innerText)',
      )),
      'A capture has an error state.',
    );
    assert(!(await evaluate('/otto/i.test(document.body.innerText)')), 'An old name remains.');
    const clip = limit
      ? await evaluate(
          `(() => {const a=document.querySelector('.usage-sentence').getBoundingClientRect();const b=document.querySelector('.statement-pop').getBoundingClientRect();const x=Math.max(0,Math.min(a.x,b.x)-16),y=Math.max(0,Math.min(a.y,b.y)-16);return {x,y,width:Math.min(innerWidth-x,Math.max(a.right,b.right)-x+16),height:Math.max(a.bottom,b.bottom)-y+16,scale:1};})()`,
        )
      : undefined;
    const screenshot = await send('Page.captureScreenshot', {
      format: 'png',
      captureBeyondViewport: false,
      ...(clip && { clip }),
    });
    await writeFile(`${output}/screens/${name}.png`, Buffer.from(screenshot.data, 'base64'));
  }
  assert.deepEqual(errors, []);
  assert.deepEqual(await evaluate('window.mediaMissingPaths'), [], 'An API fixture is missing.');
  await writeFile(`${output}/scenes.json`, JSON.stringify(scenes, null, 2));
  console.log(`Captured ${scenes.length} scenes with no page errors.`);
} finally {
  socket?.close();
  chrome?.kill();
  server.close();
  await rm(profile, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 });
}

body {
  margin: 0;
  overflow: hidden;
}
.tour-stage {
  position: relative;
  width: 1920px;
  height: 1080px;
  padding: 62px 76px;
  background: radial-gradient(ellipse at 90% 100%, #ffd0d9 0, transparent 55%), #fafafa;
  color: #191919;
}
.tour-brand {
  display: flex;
  align-items: center;
  gap: 13px;
  font-size: 36px;
  font-weight: 500;
  letter-spacing: -0.04em;
}
.tour-brand .brand-glyph {
  width: 40px;
  height: 40px;
}
.tour-header {
  display: flex;
  align-items: center;
  gap: 36px;
}
.tour-header > span {
  padding-left: 36px;
  border-left: 1px solid #d6d6d6;
  color: #676767;
  font-size: 24px;
}
.tour-header > small {
  margin-left: auto;
  font-size: 20px;
  color: #676767;
}
.tour-content {
  display: grid;
  grid-template-columns: 1120px 1fr;
  gap: 64px;
  align-items: center;
  height: 820px;
}
.tour-window {
  overflow: hidden;
  height: 710px;
  border: 1px solid #e0e0e0;
  border-radius: 24px;
  background: #fafafa;
  box-shadow: 0 24px 70px #44001b12;
}
.tour-window > header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 68px;
  padding: 0 30px;
  background: #f1f1f1;
  border-bottom: 1px solid #e0e0e0;
  font-size: 18px;
  color: #676767;
}
.tour-window > header .tour-brand {
  font-size: 24px;
  gap: 9px;
  color: #191919;
}
.tour-window > header .brand-glyph {
  width: 28px;
  height: 28px;
}
.tour-window-body {
  position: relative;
  height: calc(100% - 68px);
  padding: 28px;
}
.tour-messages {
  --text-control: 22px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  padding: 6px 16px;
  font-size: 20px;
}
.tour-messages .message {
  width: 100%;
}
.tour-messages .message-user {
  align-self: flex-end;
}
.tour-messages .message-bubble {
  padding: 16px 20px;
}
.tour-messages .message-time {
  font-size: 11px;
}
.tour-composer {
  position: absolute;
  left: 42px;
  right: 42px;
  bottom: 30px;
  height: 94px;
  border: 1px solid #e0e0e0;
  border-radius: 22px;
  padding: 19px 23px;
  color: #676767;
  font-size: 19px;
  background: #fff;
  box-shadow: 0 0 0 4px #ffe8ec;
}
.tour-composer span {
  float: right;
  display: grid;
  place-items: center;
  height: 36px;
  width: 36px;
  border-radius: 50%;
  background: #ffd0d9;
  color: #191919;
  margin-top: 24px;
}
.tour-content aside h1 {
  font-size: 54px;
  line-height: 1.08;
  letter-spacing: -0.045em;
  margin: 0 0 45px;
  max-width: 540px;
}
.tour-content aside ol {
  list-style: none;
  display: grid;
  gap: 32px;
  margin: 0;
  padding: 0;
}
.tour-content aside li {
  display: flex;
  gap: 18px;
  align-items: flex-start;
  font-size: 25px;
  line-height: 1.4;
  color: #464646;
}
.tour-content aside li b {
  flex: none;
  display: grid;
  place-items: center;
  height: 36px;
  width: 36px;
  border-radius: 50%;
  background: #ffe8ec;
  color: #87003c;
  font-size: 17px;
  font-weight: 500;
}
.tour-cover {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  height: 800px;
  text-align: center;
}
.tour-cover .tour-brand {
  font-size: 58px;
  gap: 20px;
  margin-bottom: 36px;
}
.tour-cover .tour-brand .brand-glyph {
  width: 68px;
  height: 68px;
}
.tour-cover h1 {
  font-size: 106px;
  line-height: 1;
  letter-spacing: -0.055em;
  font-weight: 600;
}
.tour-cover p {
  margin-top: 30px;
  font-size: 36px;
  color: #676767;
  letter-spacing: -0.02em;
}
.tour-cover > div:last-child {
  display: flex;
  gap: 16px;
  margin-top: 58px;
}
.tour-cover > div:last-child > span {
  padding: 13px 22px;
  border: 1px solid #e0e0e0;
  border-radius: 999px;
  font-size: 22px;
  background: #ffffff90;
}
.tour-footer {
  position: absolute;
  bottom: 50px;
  left: 76px;
  right: 76px;
  display: flex;
  justify-content: space-between;
  font-size: 16px;
  color: #676767;
}
.tour-footer > div {
  position: absolute;
  top: 38px;
  height: 3px;
  width: 100%;
  border-radius: 3px;
  background: #eaeaea;
  overflow: hidden;
}
.tour-footer i {
  display: block;
  height: 100%;
  background: #87003c;
}
.tour-window .credential-embedded {
  height: 100%;
  display: grid;
  place-items: center;
}
.tour-window .credential-card {
  width: 480px;
  font-size: 18px;
}
.tour-window .credential-card h1 {
  font-size: 28px;
}
.tour-window .content-page.secondary-page {
  padding: 16px 12px;
}
.tour-window .secondary-heading {
  margin-bottom: 24px;
}
.tour-window .statement-summary {
  font-size: 28px;
}
body[data-kind='usage'] .content-page.secondary-page,
body[data-kind='vault'] .content-page.secondary-page,
body[data-kind='usage-limit'] .content-page.secondary-page {
  padding: 32px 36px;
}

body[data-kind='usage-card'] .content-page.secondary-page {
  padding: 12px 8px;
}

.tour-messages .message .message-text {
  font-size: 22px;
  line-height: 1.5;
}
